INSERT INTO changelog (title, body, created_at) VALUES ('Центр і Огляд клієнта — менше дублів', 'Центр: у «Зараз важливо» борг показується одним пунктом на клієнта (сумою), без повторів «борг по оплаті». Порожній графік «Отримано по місяцях» замінено підказкою, як записувати оплати одним натиском. Огляд клієнта: прибрано плитку «Послуги» (вони є в лівому меню), «Ідеї» — тільки якщо є ідеї, у «Що зроблено» — по одному рядку на запис.', datetime('now'));
